import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import { getMatchId } from "../api";

function MatchDetailPage() {
  const { matchId } = useParams();
  const [match, setMatch] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchMatch = async () => {
      setLoading(true);
      const data = await getMatchId(matchId);
      setMatch(data);
      setLoading(false);
    };
    fetchMatch();
  }, [matchId]);

  const dateTime = (utcDate) => {
    if (!utcDate) return "";
    const date = new Date(utcDate);
    return date.toLocaleString("ru-RU", {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const getPredictOutcomeStyle = (outcome) => {
    if (outcome === "Win Home")
      return {
        text: "Победа хозяев (П1)",
        color: "text-green-500",
        bg: "bg-green-500",
      };
    if (outcome === "Win Away")
      return {
        text: "Победа гостей (П2)",
        color: "text-red-500",
        bg: "bg-red-500",
      };
    if (outcome === "Draw")
      return {
        text: "Ничья (X)",
        color: "text-yellow-500",
        bg: "bg-yellow-500",
      };
    return { text: "Анализ...", color: "text-gray-400", bg: "bg-gray-400" };
  };

  if (loading)
    return (
      <div className="flex justify-center items-center h-64 animate-pulse text-gray-400">
        Загрузка интеллектуального анализа...
      </div>
    );
  if (!match)
    return (
      <div className="text-center py-20 text-red-500">Матч не найден.</div>
    );

  const predStyle = getPredictOutcomeStyle(match.prediction?.outcome);

  return (
    <div className="flex flex-col lg:flex-row gap-6 lg:gap-8 max-w-6xl mx-auto">
      <section className="w-full lg:flex-grow">
        {/* ВЕРХНЯЯ КАРТОЧКА: КОМАНДЫ */}
        <div className="bg-gray-900 rounded-2xl shadow-2xl p-6 md:p-10 mb-6 border border-gray-800 relative">
          <div className="flex justify-between items-center relative z-10">
            {/* Хозяева */}
            <div className="flex flex-col items-center w-5/12">
              <img
                src={match.homeTeam.logo_url}
                alt=""
                className="h-24 w-24 md:h-32 md:w-32 object-contain mb-4 drop-shadow-[0_0_15px_rgba(255,255,255,0.1)]"
              />
              <span className="text-xl md:text-2xl font-black text-white text-center uppercase tracking-tight">
                {match.homeTeam.name}
              </span>
              <div className="mt-2 px-3 py-1 bg-gray-800 rounded-full text-xs font-mono text-yellow-500">
                ELO: {Math.round(match.homeTeam.elo)}
              </div>
            </div>

            <div className="flex flex-col items-center">
              <span className="text-4xl md:text-5xl font-black text-gray-800 italic">
                VS
              </span>
              {match.status === "FINISHED" && (
                <div className="text-3xl font-black text-white mt-4 tracking-tighter">
                  {match.score.home} : {match.score.away}
                </div>
              )}
            </div>

            {/* Гости */}
            <div className="flex flex-col items-center w-5/12">
              <img
                src={match.awayTeam.logo_url}
                alt=""
                className="h-24 w-24 md:h-32 md:w-32 object-contain mb-4 drop-shadow-[0_0_15px_rgba(255,255,255,0.1)]"
              />
              <span className="text-xl md:text-2xl font-black text-white text-center uppercase tracking-tight">
                {match.awayTeam.name}
              </span>
              <div className="mt-2 px-3 py-1 bg-gray-800 rounded-full text-xs font-mono text-yellow-500">
                ELO: {Math.round(match.awayTeam.elo)}
              </div>
            </div>
          </div>

          <div className="text-center mt-8 text-gray-500 text-xs uppercase tracking-[0.2em] font-bold border-t border-gray-800 pt-6">
            {dateTime(match.utcDate)} | {match.league}
          </div>
        </div>

        {/* ПРОГНОЗ И ВЕРОЯТНОСТИ */}
        {match.prediction && (
          <div className="bg-gray-900 rounded-2xl shadow-2xl p-6 md:p-8 mb-6 border-l-4 border-red-600">
            <h3 className="text-sm font-black text-gray-500 uppercase tracking-widest mb-8">
              Интеллектуальный прогноз
            </h3>

            {/* Шкала вероятностей */}
            <div className="w-full bg-gray-800 rounded-full h-4 mb-4 flex overflow-hidden p-0.5 border border-gray-700">
              <div
                className="bg-green-500 h-full transition-all duration-1000"
                style={{ width: `${match.prediction.prob_home}%` }}
              ></div>
              <div
                className="bg-yellow-500 h-full transition-all duration-1000"
                style={{ width: `${match.prediction.prob_draw}%` }}
              ></div>
              <div
                className="bg-red-500 h-full transition-all duration-1000"
                style={{ width: `${match.prediction.prob_away}%` }}
              ></div>
            </div>

            <div className="flex justify-between text-[10px] md:text-xs font-black text-gray-400 uppercase mb-10 px-1">
              <div className="text-green-500">
                П1: {match.prediction.prob_home}%
              </div>
              <div className="text-yellow-500 text-center">
                X: {match.prediction.prob_draw}%
              </div>
              <div className="text-red-500 text-right">
                П2: {match.prediction.prob_away}%
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-black/20 p-6 rounded-xl border border-white/5">
              <div className="text-center md:text-left">
                <span className="block text-gray-500 text-[10px] uppercase font-bold mb-1">
                  Рекомендация:
                </span>
                <span
                  className={`text-xl font-black uppercase ${predStyle.color}`}
                >
                  {predStyle.text}
                </span>
              </div>
              <div className="text-center md:text-right border-t md:border-t-0 md:border-l border-gray-800 pt-4 md:pt-0 md:pl-6">
                <span className="block text-gray-500 text-[10px] uppercase font-bold mb-1">
                  Ожидаемый счет:
                </span>
                <span className="text-2xl font-black text-white italic tracking-widest">
                  {match.prediction.exact_score}
                </span>
              </div>
            </div>

            <div className="mt-6 flex justify-between items-center text-[10px] text-gray-600 font-mono">
              <div>Версия модели: {match.prediction.model_version}</div>
              <div>
                Тотал 2.5 бол:{" "}
                <span className="text-blue-400">
                  {match.prediction.total_over_2_5}%
                </span>
              </div>
            </div>
          </div>
        )}

        {/* СТАТИСТИКА (ИНТЕЛЛЕКТУАЛЬНЫЙ АНАЛИЗ) */}
        <div className="bg-gray-900 rounded-2xl shadow-2xl p-6 md:p-8 border border-gray-800">
          <h3 className="text-sm font-black text-gray-500 uppercase tracking-widest mb-6">
            Сравнение показателей (Last 5)
          </h3>

          <div className="space-y-6">
            <StatRow
              label="Средний xG"
              home={match.homeTeam.stats_last_5.xg}
              away={match.awayTeam.stats_last_5.xg}
            />
            <StatRow
              label="Интенсивность прессинга (PPDA)"
              home={match.homeTeam.stats_last_5.ppda}
              away={match.awayTeam.stats_last_5.ppda}
              reverse
            />
            <StatRow
              label="Глубокие атаки (Deep)"
              home={match.homeTeam.stats_last_5.deep}
              away={match.awayTeam.stats_last_5.deep}
            />
          </div>
        </div>
      </section>

      {/* САЙДБАР */}
      <aside className="w-full lg:w-80 hidden lg:block">
        <div className="bg-gray-900 p-6 rounded-2xl border border-gray-800 shadow-xl sticky top-24">
          <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest mb-6">
            Турнирная таблица
          </h3>
          <div className="flex flex-col items-center justify-center py-20 text-gray-700">
            <span className="text-4xl mb-4">📊</span>
            <p className="text-xs font-bold uppercase">В разработке</p>
          </div>
        </div>
      </aside>
    </div>
  );
}

// Вспомогательный компонент для строк статистики
const StatRow = ({ label, home, away, reverse = false }) => {
  const h = home || 0;
  const a = away || 0;
  // Логика: чем больше xG - тем лучше (зеленый), чем меньше PPDA - тем лучше (зеленый)
  const isHomeBetter = reverse ? h < a : h > a;

  return (
    <div>
      <div className="flex justify-between mb-2 px-1">
        <span
          className={`text-sm font-black ${isHomeBetter ? "text-green-400" : "text-gray-400"}`}
        >
          {h.toFixed(2)}
        </span>
        <span className="text-[10px] text-gray-600 uppercase font-bold">
          {label}
        </span>
        <span
          className={`text-sm font-black ${!isHomeBetter ? "text-green-400" : "text-gray-400"}`}
        >
          {a.toFixed(2)}
        </span>
      </div>
      <div className="flex w-full h-1.5 bg-gray-800 rounded-full overflow-hidden">
        <div
          className={`h-full ${isHomeBetter ? "bg-green-500" : "bg-gray-700"}`}
          style={{ width: `${(h / (h + a)) * 100}%` }}
        ></div>
        <div
          className={`h-full ${!isHomeBetter ? "bg-green-500" : "bg-gray-700"}`}
          style={{ width: `${(a / (h + a)) * 100}%` }}
        ></div>
      </div>
    </div>
  );
};

export default MatchDetailPage;
